    md += `- **Service Worker Detected:** ${bundle.hasServiceWorker ? 'Yes (PWA Enabled)' : 'No'}\n`;
    md += `- **SourceMaps Exposed:** ${bundle.hasSourceMaps ? '⚠️ Yes (Original source code reconstructible)' : 'No'}\n\n`;
